// Logical actions stay stable; key bindings are user preferences, not save data.
export const KEY_ACTIONS=[['w','Move up'],['s','Move down'],['a','Move left'],['d','Move right'],['shift','Sprint'],['q','Dodge'],['r','Substitution'],['j','Melee combo'],['k','Shuriken'],['l','Shadow clones'],[' ','Rasengan'],['f','Fuma technique'],['g','Advanced technique'],['e','Interact'],['t','Kyubi'],['i','Inventory'],['p','Skill tree'],['m','Map'],['u','Journal'],['c','Characters'],['n','Chunin exams'],['1','Quick item 1'],['2','Quick item 2'],['3','Quick item 3']];
const DEFAULTS=Object.fromEntries(KEY_ACTIONS.map(([k])=>[k,k])),STORAGE='shinobi25d.controls.v1';
const allowed=k=>/^[a-z0-9]$/.test(k)||[' ','shift','arrowup','arrowdown','arrowleft','arrowright'].includes(k);
export function createKeyBindings(storage){let mapping={...DEFAULTS};try{const raw=JSON.parse(storage.getItem(STORAGE)||'null');if(raw&&KEY_ACTIONS.every(([a])=>allowed(raw[a]))&&new Set(KEY_ACTIONS.map(([a])=>raw[a])).size===KEY_ACTIONS.length)mapping=Object.fromEntries(KEY_ACTIONS.map(([a])=>[a,raw[a]]));}catch{}
function persist(){try{storage.setItem(STORAGE,JSON.stringify(mapping));}catch{}}
return {action(k){k=k.toLowerCase();return Object.keys(mapping).find(a=>mapping[a]===k)||({arrowup:'w',arrowdown:'s',arrowleft:'a',arrowright:'d'}[k])||(k==='escape'?'escape':'');},label(a){const k=mapping[a]??a;return ({' ':'Space',shift:'Shift',arrowup:'↑',arrowdown:'↓',arrowleft:'←',arrowright:'→'}[k]||k.toUpperCase());},assign(a,k){if(!Object.hasOwn(DEFAULTS,a)||!allowed(k))return 'Choose a letter, number, Space, Shift or arrow key.';const other=Object.keys(mapping).find(x=>x!==a&&mapping[x]===k);if(other)return 'That key is already assigned to '+KEY_ACTIONS.find(([x])=>x===other)[1]+'.';mapping[a]=k;persist();return '';},reset(){mapping={...DEFAULTS};persist();}};
}
